{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "Cloud Run service is publicly accessible via allUsers binding",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "HIGH",
      "explanation": "The IAM binding grants the 'roles/run.invoker' role to 'allUsers', making the Cloud Run service anonymously accessible to anyone on the internet. This exposes the application to unauthorized access, potential abuse, and data leakage unless explicitly intended for a public-facing endpoint."
    }
  ],
  "patched_code": "resource \"google_cloud_run_service_iam_binding\" \"search_service_public\" {\n  location = google_cloud_run_service.search_service.location\n  project  = google_cloud_run_service.search_service.project\n  service  = google_cloud_run_service.search_service.name\n  role     = \"roles/run.invoker\"\n  members = [\n    # Removed \"allUsers\" to prevent anonymous public access.\n    # Add specific service accounts or user emails here as required by your security policy.\n  ]\n}",
  "fix_summary": "Removed the 'allUsers' member from the IAM binding to disable anonymous public access to the Cloud Run service. The resource remains defined but requires explicit member configuration to grant access."
}
